<script setup lang="ts">
import{computed,nextTick,onMounted,onUnmounted,ref,watch}from'vue';
import{sampleRangeColor}from'../../../packages/comp-bridge/color-range.mjs';
import{parityMessages}from'./parity-labels';
import type{Language,OpenResult}from'./types';
const props=defineProps<{language:Language;png:Uint8Array;apply:(settings:Record<string,unknown>)=>Promise<OpenResult>}>(),emit=defineEmits(['close','running']),t=computed(()=>parityMessages[props.language]);
const imageCanvas=ref<HTMLCanvasElement>(),maskCanvas=ref<HTMLCanvasElement>(),include=ref<number[][]>([]),exclude=ref<number[][]>([]),mode=ref('replace'),fuzziness=ref(40),invert=ref(false),busy=ref(false),computing=ref(false),error=ref(''),selectedCount=ref(0),loaded=ref(false),sampleX=ref(0),sampleY=ref(0),imageWidth=ref(1),imageHeight=ref(1);
let image:ImageData|undefined,worker:Worker|undefined,generation=0,timer:ReturnType<typeof setTimeout>|undefined,workerTimer:ReturnType<typeof setTimeout>|undefined,live=true;
const settings=()=>({include:include.value.map(color=>[...color]),exclude:exclude.value.map(color=>[...color]),fuzziness:fuzziness.value,invert:invert.value});
function takeSample(event?:MouseEvent){if(!image||busy.value)return;if(!Number.isFinite(sampleX.value)||!Number.isFinite(sampleY.value)){error.value=t.value.failed;return;}const color=sampleRangeColor(image,sampleX.value,sampleY.value);if(!color)return;const selectedMode=event?.altKey?'remove':event?.shiftKey?'add':mode.value;if(selectedMode==='replace'){include.value=[color];exclude.value=[];}else{const list=selectedMode==='remove'?exclude:include;if(list.value.length>=32){error.value=t.value.rangeLimit;return;}if(!list.value.some(existing=>existing.every((channel,index)=>channel===color[index])))list.value=[...list.value,color];}}
function sample(event:MouseEvent){if(!image)return;const rect=imageCanvas.value!.getBoundingClientRect();sampleX.value=Math.min(image.width-1,Math.max(0,Math.floor((event.clientX-rect.left)*image.width/rect.width)));sampleY.value=Math.min(image.height-1,Math.max(0,Math.floor((event.clientY-rect.top)*image.height/rect.height)));takeSample(event);}

function preview(){
  const own=++generation;worker?.terminate();worker=undefined;clearTimeout(timer);clearTimeout(workerTimer);error.value='';if(!include.value.length){computing.value=false;selectedCount.value=0;maskCanvas.value?.getContext('2d')?.clearRect(0,0,maskCanvas.value.width,maskCanvas.value.height);return;}computing.value=true;
  timer=setTimeout(()=>{if(!image)return;const task=worker=new Worker(new URL('./color-range-worker.ts',import.meta.url),{type:'module'}),copy=new Uint8ClampedArray(image.data);task.onmessage=event=>{if(!live||own!==generation)return;computing.value=false;clearTimeout(workerTimer);if(event.data.error){task.terminate();if(worker===task)worker=undefined;error.value=t.value.failed;return;}const mask=event.data.mask as Uint8Array;selectedCount.value=mask.reduce((count,value)=>count+(value?1:0),0);const canvas=maskCanvas.value;if(!canvas||!image)return;const context=canvas.getContext('2d')!,pixels=context.createImageData(canvas.width,canvas.height);for(let y=0;y<canvas.height;y++)for(let x=0;x<canvas.width;x++){const value=mask[Math.min(image.height-1,Math.floor((y+.5)*image.height/canvas.height))*image.width+Math.min(image.width-1,Math.floor((x+.5)*image.width/canvas.width))],index=(y*canvas.width+x)*4;pixels.data[index]=pixels.data[index+1]=pixels.data[index+2]=value;pixels.data[index+3]=255;}context.putImageData(pixels,0,0);task.terminate();if(worker===task)worker=undefined;};task.onerror=()=>{task.terminate();clearTimeout(workerTimer);if(own===generation){computing.value=false;error.value=t.value.failed;}};workerTimer=setTimeout(()=>{task.terminate();if(live&&own===generation){computing.value=false;error.value=t.value.failed;}},30000);task.postMessage({image:{width:image.width,height:image.height,data:copy},settings:settings()},[copy.buffer]);},60);
}
watch([include,exclude,fuzziness,invert],preview,{deep:true});
async function apply(){busy.value=true;error.value='';try{const result=await props.apply(settings());if(result.error)error.value=t.value.failed;else emit('close');}catch{error.value=t.value.failed;}finally{busy.value=false;}}
onMounted(async()=>{emit('running',true);try{const bitmap=await createImageBitmap(new Blob([new Uint8Array(props.png)],{type:'image/png'}));try{await nextTick();if(!live||!imageCanvas.value||!maskCanvas.value)return;const canvas=imageCanvas.value;canvas.width=bitmap.width;canvas.height=bitmap.height;imageWidth.value=bitmap.width;imageHeight.value=bitmap.height;const context=canvas.getContext('2d',{willReadFrequently:true})!;context.drawImage(bitmap,0,0);image=context.getImageData(0,0,bitmap.width,bitmap.height);const scale=Math.min(1,600/bitmap.width,320/bitmap.height);maskCanvas.value.width=Math.max(1,Math.round(bitmap.width*scale));maskCanvas.value.height=Math.max(1,Math.round(bitmap.height*scale));loaded.value=true;}finally{bitmap.close();}}catch{error.value=t.value.failed;}});
onUnmounted(()=>{live=false;generation++;clearTimeout(timer);clearTimeout(workerTimer);worker?.terminate();image=undefined;emit('running',false);});
</script>
<template><div class="modal-shade" @click.self="!busy&&emit('close')" @keydown.esc.stop.prevent="!busy&&emit('close')"><section class="dialog range-dialog" role="dialog" aria-modal="true" :aria-label="t.colorRange"><h2>{{t.colorRange}}</h2><p>{{t.rangeTip}}</p><p v-if="error" role="alert">{{error}}</p><div class="range-previews"><figure><figcaption>{{t.rangeSample}}</figcaption><canvas ref="imageCanvas" data-testid="range-source" tabindex="0" :aria-label="t.rangeSample" @click="sample"></canvas></figure><figure><figcaption>{{t.rangeMask}} · {{selectedCount}}</figcaption><canvas ref="maskCanvas" data-testid="range-mask" :aria-label="t.rangeMask"></canvas></figure></div><fieldset :disabled="busy||!loaded"><label>X<input v-model.number="sampleX" data-testid="range-x" type="number" min="0" :max="imageWidth-1"></label><label>Y<input v-model.number="sampleY" data-testid="range-y" type="number" min="0" :max="imageHeight-1"></label><button data-testid="range-sample" @click="takeSample()">{{t.rangeSample}}</button><label>{{t.rangeMode}}<select v-model="mode" data-testid="range-mode"><option value="replace">{{t.rangeReplace}}</option><option value="add">{{t.rangeAdd}}</option><option value="remove">{{t.rangeRemove}}</option></select></label><label>{{t.rangeFuzziness}}<input v-model.number="fuzziness" data-testid="range-fuzziness" type="number" min="0" max="200"></label><label><input v-model="invert" data-testid="range-invert" type="checkbox">{{t.rangeInvert}}</label></fieldset><p class="range-samples">{{t.rangeAdd}}: {{include.length}} · {{t.rangeRemove}}: {{exclude.length}} <span v-for="(color,index) in include" :key="index" :style="{background:`rgb(${color.join(',')})`}"></span></p><div class="button-row dialog-actions"><span v-if="computing" role="status">{{t.loading}}</span><button :disabled="busy" @click="emit('close')">{{t.cancel}}</button><button class="primary" data-testid="range-apply" :disabled="busy||computing||!loaded||!include.length||!!error" @click="apply">{{t.apply}}</button></div></section></div></template>
<style scoped>.range-dialog{width:min(1000px,96vw);max-height:94vh;overflow:auto}.range-previews{display:grid;grid-template-columns:1fr 1fr;gap:12px}.range-previews figure{margin:0;min-width:0}.range-previews canvas{display:block;max-width:100%;max-height:320px;object-fit:contain;background:#000}.range-previews [data-testid=range-source]{cursor:crosshair}.range-samples span{display:inline-block;width:16px;height:16px;margin-left:4px;border:1px solid #999}fieldset{display:flex;flex-wrap:wrap;align-items:center;gap:16px;border:0;margin:12px 0;padding:0}p[role=alert]{color:#ffb4b4}</style>
